 "content": "from collections import Counter


def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    color = min((v for v in counts if v != bg), key=lambda v: counts[v])
    seeds = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
    if not seeds:
        return [row[:] for row in grid]

    r0 = min(r for r, c in seeds)
    c0 = min(c for r, c in seeds)
    shape = {(r - r0, c - c0) for r, c in seeds}
    bh = max(r for r, c in shape) + 1
    bw = max(c for r, c in shape) + 1
    out = [row[:] for row in grid]

    # Duplicate the marked stencil at every translation whose marked cells
    # fall on zero cells. The cells inside its bounding box that are not part
    # of the stencil do not constrain a placement.
    for r in range(h - bh + 1):
        for c in range(w - bw + 1):
            if all(grid[r + dr][c + dc] == 0 for dr, dc in shape):
                for dr, dc in shape:
                    out[r + dr][c + dc] = color
    return out
